"""
安全代码执行器。
沙箱执行 Z3 / Python 代码，超时保护 + 异常捕获。
"""

import io
import signal
import traceback
from contextlib import redirect_stdout, redirect_stderr
from dataclasses import dataclass, asdict
from typing import Optional

from config import EXEC_TIMEOUT


class ExecutionTimeout(Exception):
    pass


def _alarm_handler(signum, frame):
    raise ExecutionTimeout("Execution timed out")


@dataclass
class ExecResult:
    output: str
    error: Optional[str]
    verdict: str              # "True" / "False" / "Unknown" / "Error"
    timed_out: bool

    def to_dict(self):
        return asdict(self)


def _parse_verdict(output: str) -> str:
    lines = [l.strip() for l in output.strip().splitlines() if l.strip()]
    if not lines:
        return "Error"

    last = lines[-1].lower()
    if last in ("true", "entailed"):
        return "True"
    if last in ("false", "contradicted"):
        return "False"
    if last in ("unknown", "neutral", "uncertain"):
        return "Unknown"
    return "Error"


def execute_code(code: str, timeout: int = EXEC_TIMEOUT) -> ExecResult:
    stdout_buf = io.StringIO()
    stderr_buf = io.StringIO()

    prev_handler = signal.signal(signal.SIGALRM, _alarm_handler)
    signal.alarm(timeout)

    try:
        with redirect_stdout(stdout_buf), redirect_stderr(stderr_buf):
            exec(code, {"__builtins__": __builtins__})

        output = stdout_buf.getvalue()
        return ExecResult(
            output=output,
            error=None,
            verdict=_parse_verdict(output),
            timed_out=False,
        )

    except ExecutionTimeout:
        return ExecResult(
            output=stdout_buf.getvalue(),
            error="Execution timed out",
            verdict="Error",
            timed_out=True,
        )
    except Exception as e:
        return ExecResult(
            output=stdout_buf.getvalue(),
            error=f"{type(e).__name__}: {e}\n{traceback.format_exc()}",
            verdict="Error",
            timed_out=False,
        )
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, prev_handler)

"""
FOLIO 数据集加载器。
从本地 JSONL 文件加载 validation set，输出 (id, premises, conclusion, label) 结构。
"""

import json
from dataclasses import dataclass, asdict
from typing import List, Optional
from pathlib import Path

from config import PROJECT_ROOT

_LABEL_NORM = {
    "true": "True",
    "false": "False",
    "unknown": "Unknown",
    "uncertain": "Unknown",
}

FOLIO_PATH = PROJECT_ROOT / "data" / "folio-validation.jsonl"


@dataclass
class FolioExample:
    id: str
    premises: str
    conclusion: str
    label: str           # "True" / "False" / "Unknown"

    def to_dict(self):
        return asdict(self)


def _normalize_label(raw) -> str:
    if isinstance(raw, int):
        return ["True", "False", "Unknown"][raw]
    return _LABEL_NORM.get(str(raw).strip().lower(), "Unknown")


def _normalize_premises(raw) -> str:
    if isinstance(raw, list):
        return " ".join(raw)
    return str(raw)


def load_folio(
    max_examples: Optional[int] = None,
) -> List[FolioExample]:
    with open(FOLIO_PATH) as f:
        rows = [json.loads(line) for line in f if line.strip()]

    examples = []
    for i, row in enumerate(rows):
        if max_examples and i >= max_examples:
            break

        examples.append(FolioExample(
            id=f"folio_validation_{i}",
            premises=_normalize_premises(row["premises"]),
            conclusion=row["conclusion"],
            label=_normalize_label(row["label"]),
        ))

    return examples

